<?php
declare(strict_types=1);namespace Pam\Native\Intents;use Closure;use InvalidArgumentException;use Pam\Native\Modules\NativeModuleResult;use Pam\Native\Modules\NativeModules;final class Intents{/** @param list<IntentAction>$actions */public function register(array$actions,Closure$complete):int{if(count($actions)>15)throw new InvalidArgumentException('At most 15 intent actions are supported.');foreach($actions as$a)if(!$a instanceof IntentAction)throw new InvalidArgumentException('Actions must be IntentAction values.');return NativeModules::call('intents','register',['json'=>json_encode($actions,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES)],static fn(NativeModuleResult$r)=>$complete($r->succeeded(),$r->succeeded()?null:$r->message()));}public function clear(Closure$complete):int{return$this->register([],$complete);}}
